const expenses = $json.body.expenses || [];
const message = $json.body.message || "No message";

let summary = "Data:\n";
let totalSpent = 0;
let largestBooking = null;
let byCategory = {};

if (expenses.length > 0) {
  expenses.forEach((item, index) => {
    const price = Number(item.price) || 0;
    totalSpent += price;
    if (!largestBooking || price > Number(largestBooking.price)) largestBooking = item;

    const type = item.roomType || 'Unknown';
    if (!byCategory[type]) byCategory[type] = 0;
    byCategory[type] += price;

    // تم إضافة Guest: ${item.guestName} فقط لهذا السطر
    summary += `${index + 1}. Guest: ${item.guestName}, Hotel: ${item.hotelName}, Type: ${type}, Price: $${price}, Dates: ${item.checkIn} to ${item.checkOut}.\n`;
  });

  let categoryString = Object.entries(byCategory).map(([key, val]) => `${key}: $${val}`).join(', ');

  summary += `\nTotal Spending: $${totalSpent}`;
  summary += `\nLargest Booking: ${largestBooking.hotelName} ($${largestBooking.price})`;
  summary += `\nSpending by Category: ${categoryString}`;
} else {
  summary += "No bookings found.";
}

return { json: { message: message, summary: summary } };
